import {STYLE,POLICY,uid,blankLibrary,assertSafe,characterText,validateCharacter,normalizePlan,newPanel,clampPanelCount,buildEpisodePages,panelJob,EPISODE_MAX_PANELS,EPISODE_MAX_PAGES,PAGE_MAX_PANELS} from './core.js';
import {getLibrary,saveLibrary,getAsset,putAsset,rasterize,exportLibrary,importLibrary} from './db.js';
import {Provider,readSettings,writeSettings,localBase,pickerModels,modelLabel,isCancelled} from './provider.js';
import {runPanelBatch} from './batch.js';
import {BUBBLE_PRESETS,createBubble,renderLettering,seedBubbles,dragUpdate,applyBubbleElement,flipTail,setFontSize,coverRect,paintBubbles,tailMarkup} from './bubbles.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='secondary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const input=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',extra='')=>`<label>${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
let lib=blankLibrary(), settings=readSettings(), nav='library', sid=null,eid=null,tab='write',busy=false,draft=null,readerIndex=0;
let persist=Promise.resolve(), saveTimer,noticeTimer,batchAbort=null,lettering=null,bubbleGesture=null;const assetURLs=new Map();
const provider=new Provider(settings,ask,(message)=>notify(message));
function series(){return lib.series.find(s=>s.id===sid);}
function episode(){return series()?.episodes.find(e=>e.id===eid);}
function allPanels(e=episode()){return e?.pages?.flatMap(p=>p.panels)||[];}
function panelCount(){return clampPanelCount(settings.panelCount);}
function resumeLabel(){const panels=allPanels();if(!panels.length)return '';const done=panels.filter(p=>p.imageId).length;if(done>=panels.length)return '';return `Resume images (${done}/${panels.length})`;}
function selectedCharacters(ids=episode()?.cast||[]){return lib.characters.filter(c=>ids.includes(c.id));}
function panelById(id){return episode()?.pages.flatMap(p=>p.panels).find(x=>x.id===id);}
function notify(message,error=false){const n=$('#notice');n.hidden=false;n.textContent=message;n.classList.toggle('error',error);clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.hidden=true,error?14000:6500);}
function saving(text){$$('.save-status').forEach(n=>n.textContent=text);}
function save(){clearTimeout(saveTimer);saving('Saving on this device…');const snapshot=structuredClone(lib);persist=persist.catch(()=>{}).then(()=>saveLibrary(snapshot));persist.then(()=>saving('Saved on this device · back up regularly'),e=>{saving('Not saved — export a backup now');notify('Storage failed: '+e.message+' Your latest changes may not survive closing the app.',true);});return persist;}
function queueSave(){saving('Saving…');clearTimeout(saveTimer);saveTimer=setTimeout(save,350);}
async function flush(){clearTimeout(saveTimer);await save();await persist;}
function setBusy(v){busy=v;$$('[data-ai], [data-mutates], [data-action="import"], [data-action="export"]').forEach(b=>b.disabled=v);$('#modeBadge').textContent=v?'WORKING…':settings.demo?'OFFLINE DEMO':'LIVE MODE';}
async function run(fn){if(busy)return;setBusy(true);try{await fn();}catch(e){notify(e.message||'Something went wrong. Try again.',true);}finally{setBusy(false);}}
function ask(title,message,label='Continue'){return new Promise(resolve=>{const d=document.createElement('dialog');d.setAttribute('aria-label',title);d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(message)}</p><div class="sticky-actions"><button type="button" data-no class="secondary">Cancel</button><button type="button" data-yes>${esc(label)}</button></div>`;document.body.append(d);let done=false;const finish=v=>{if(done)return;done=true;d.close();d.remove();resolve(v);};d.querySelector('[data-no]').onclick=()=>finish(false);d.querySelector('[data-yes]').onclick=()=>finish(true);d.addEventListener('cancel',e=>{e.preventDefault();finish(false);});d.showModal();});}
function showModal(html){$('#modalContent').innerHTML=html;const d=$('#modal');if(!d.open)d.showModal();hydrate(d);}
function closeModal(){if($('#modal').open)$('#modal').close();draft=null;}
async function assetURL(id){if(!id)return null;if(assetURLs.has(id))return assetURLs.get(id);const a=await getAsset(id);if(!a)return null;const u=URL.createObjectURL(a.blob);assetURLs.set(id,u);return u;}
function hydrate(root=document){root.querySelectorAll('[data-image-id]').forEach(async n=>{try{const u=await assetURL(n.dataset.imageId);if(u){n.src=u;n.hidden=false;}}catch{notify('An image could not be loaded from device storage.',true);}});}
function refMarkup(id,cls='char-ref'){return id?`<img class="${cls}" data-image-id="${esc(id)}" alt="Fictional character reference artwork" hidden>`:'';}
function render(){
  $$('.bottom-nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===nav));
  if(nav==='settings')$('#app').innerHTML=settingsView();else if(nav==='characters')$('#app').innerHTML=charactersView();else if(episode())$('#app').innerHTML=episodeView();else if(series())$('#app').innerHTML=seriesView();else $('#app').innerHTML=libraryView();
  setBusy(busy);hydrate($('#app'));
}
function libraryView(){return `<section class="hero"><div class="hero-text"><p class="eyebrow">Your worlds, together</p><h1>A little imagination.<br>A whole new world.</h1><p>Create a cast. Write your story. Turn it into a comic you can keep coming back to.</p>${button('＋ New series','new-series','', 'data-mutates')}</div><div class="hero-art" aria-hidden="true"><span class="big-star">✦</span><div><p class="eyebrow">Made by the two of you</p><h2>Every great story<br>starts with “what if?”</h2></div></div></section><div class="section-heading"><h2>Your library <span class="muted">${lib.series.length}</span></h2><span class="pill">ON THIS DEVICE</span></div>${lib.series.length?`<div class="grid">${lib.series.map(s=>`<article class="card series-card"><div class="series-cover"><h3>${esc(s.title)}</h3></div><div class="series-info"><p>${esc(s.synopsis||'Your next story is waiting.')}</p><div class="row between"><span class="pill">${s.episodes.length} EPISODE${s.episodes.length===1?'':'S'}</span><span class="muted">Ongoing series</span></div><br>${button('Open series →','open-series','secondary',`data-id="${s.id}"`)}</div></article>`).join('')}</div>`:`<div class="empty"><h3>Your shelf is a blank canvas.</h3><p>Start a series or explore a fictional sample.</p>${button('Try a sample story','sample','secondary','data-mutates')}</div>`}<p class="status-line">Private by default: no sign-in, tracking, or automatic API requests. Mature and explicit stories between consenting fictional adults 18+.</p>`;}
function charactersView(){return `<p class="eyebrow">The cast behind the story</p><div class="section-heading"><h1>Your characters</h1>${button('＋ New','new-character','','data-mutates')}</div><p class="muted">Save their look, personality, and past. Their profiles travel with each story request.</p>${lib.characters.length?`<div class="grid">${lib.characters.map(c=>`<article class="card"><div class="char-preview">${c.refId?refMarkup(c.refId,'avatar'):`<div class="avatar">${esc(c.name[0])}</div>`}<div><h3>${esc(c.name)}</h3><span class="pill">FICTIONAL · ${c.age}+</span></div></div><p class="muted" style="margin:15px 0">${esc(c.description.slice(0,180))}</p>${button('Edit character','edit-character','secondary',`data-id="${c.id}" data-mutates`)}</article>`).join('')}</div>`:`<div class="empty"><h3>Who lives in your world?</h3><p>Describe a fictional adult, choose presets, or upload a reference sheet.</p>${button('Create your first character','new-character','','data-mutates')}</div>`}`;}
function seriesView(){const s=series();return `${button('← Your library','back-library','back')}<p class="eyebrow">Ongoing series</p><h1>${esc(s.title)}</h1><p class="muted">${esc(s.synopsis)}</p><div class="toolbar">${button('＋ New episode','new-episode','','data-mutates')}${button('Series & art style','edit-series','secondary','data-mutates')}</div><div class="section-heading"><h2>Episodes</h2><span class="muted">${s.episodes.length} chapters so far</span></div>${s.episodes.length?s.episodes.map((e,i)=>`<article class="card episode-row"><div><span class="eyebrow">EPISODE ${String(i+1).padStart(2,'0')}</span><h3>${esc(e.title)}</h3><small>${e.pages.length} pages · ${e.pages.reduce((n,p)=>n+p.panels.length,0)} panels</small></div>${button('Open →','open-episode','secondary',`data-id="${e.id}"`)}</article>`).join(''):'<div class="empty">Your first episode starts here. Write a scene, then let AI propose a storyboard.</div>'}<details><summary>Art direction</summary><p class="muted">${esc(s.style)}</p></details><p class="status-line save-status">Saved on this device · back up regularly</p>`;}
function castCheckboxes(ids,attrs=''){return `<div class="cast">${lib.characters.map(c=>`<label class="check"><input type="checkbox" value="${c.id}" ${ids.includes(c.id)?'checked':''} ${attrs}>${esc(c.name)} <small>${c.age}</small></label>`).join('')}</div>`;}
function episodeView(){const e=episode(),s=series();const resume=resumeLabel();return `${button('← '+esc(s.title),'back-series','back')}<p class="eyebrow">The episode studio</p><h1>${esc(e.title)}</h1><div class="tabs" role="tablist" aria-label="Episode workspace"><button role="tab" aria-selected="${tab==='write'}" class="${tab==='write'?'active':''}" data-tab="write">Write</button><button role="tab" aria-selected="${tab==='panels'}" class="${tab==='panels'?'active':''}" data-tab="panels">Storyboard</button><button role="tab" aria-selected="false" data-action="read">Read ↗</button></div>${tab==='write'?`<div class="card">${input('Episode title','episodeTitle',e.title,'text','data-bind="episode-title" maxlength="200"')}<label>Characters in this episode</label>${lib.characters.length?castCheckboxes(e.cast,'data-bind="episode-cast"'):`<p class="muted">Create at least one fictional adult character before using AI.</p>${button('Create a character','new-character','secondary','data-mutates')}`}${area('Your script','script',e.script,'data-bind="script" rows="14" maxlength="60000" placeholder="Write the scene in your own words. Add dialogue, action, and atmosphere…"')}<p class="muted">You write; AI is the editor, not the author. Review every change before applying it.</p><div class="toolbar">${button('✦ AI polish','polish','','data-ai')}${button('✦ Plan pages','plan','secondary','data-ai')}${button(`✦ Generate ${panelCount()}-panel comic`,'generate-comic','','data-ai')}${resume?button(resume,'resume-comic','secondary','data-ai'):''}${e.previousScript?button('Undo last polish','undo-polish','ghost','data-mutates'):''}</div><p class="save-status status-line">Saved on this device · back up regularly</p></div>`:panelsView()}<div class="help">${settings.demo?'Offline demo is on. AI buttons return local sample responses; no network calls or credits.':'Live mode: writing uses Venice. Images prefer your local server if configured. A full comic asks once, then illustrates each panel in order. You can cancel and resume.'}</div>`;}
function preview(p,opts={}){const lines=(p.dialogue||'').split('\n').map(x=>x.trim()).filter(Boolean);const custom=Array.isArray(p.bubbles)&&p.bubbles.length;const legacy=!custom&&lines.length?`<div class="bubbles ${p.bubblePosition==='bottom'?'bottom':''}">${lines.slice(0,6).map(l=>{const i=l.indexOf(':');return `<div class="bubble">${i>0&&i<60?`<b>${esc(l.slice(0,i))}</b>${esc(l.slice(i+1).trim())}`:esc(l)}</div>`;}).join('')}</div>`:'';const caption=!custom&&p.caption?`<div class="caption ${p.captionPosition==='top'?'top':''}">${esc(p.caption)}</div>`:'';const edit=opts.edit&&p.imageId?`<button type="button" class="bubble-jump" data-action="edit-bubbles" data-id="${esc(p.id)}">Bubbles</button>`:'';return `${p.imageId?`<img data-image-id="${esc(p.imageId)}" alt="Generated comic panel" hidden>`:`<div class="placeholder"><span class="symbol">✧</span><span>${esc(p.camera||'Your next scene')}</span><small>Generate this panel to add art</small></div>`}${custom?renderLettering(p.bubbles):''}${legacy}${caption}${edit}`;}
function panelCard(p,pi){return `<article class="panel-card" data-panel="${p.id}"><div class="panel-art" data-preview="${p.id}">${preview(p)}</div><div class="panel-fields"><div class="row between"><strong>Panel ${pi+1}</strong>${button('Remove','remove-panel','ghost small',`data-id="${p.id}" data-mutates`)}</div><label>Camera / angle<input data-panel-field="camera" data-id="${p.id}" value="${esc(p.camera)}" list="cameraAngles" maxlength="200"></label><label>Scene prompt<textarea data-panel-field="prompt" data-id="${p.id}" maxlength="5000">${esc(p.prompt)}</textarea></label><details><summary>Characters & lettering</summary><label>Characters in this panel</label>${castCheckboxes(p.cast,`data-panel-cast="${p.id}"`)}<label>Dialogue · one Name: line per bubble<textarea data-panel-field="dialogue" data-id="${p.id}" maxlength="2000">${esc(p.dialogue)}</textarea></label><label>Bubble position<select data-panel-field="bubblePosition" data-id="${p.id}"><option value="top" ${p.bubblePosition==='top'?'selected':''}>Top</option><option value="bottom" ${p.bubblePosition==='bottom'?'selected':''}>Bottom</option></select></label><label>Caption<textarea data-panel-field="caption" data-id="${p.id}" maxlength="1000">${esc(p.caption)}</textarea></label><label>Caption position<select data-panel-field="captionPosition" data-id="${p.id}"><option value="bottom" ${p.captionPosition==='bottom'?'selected':''}>Bottom</option><option value="top" ${p.captionPosition==='top'?'selected':''}>Top</option></select></label></details><p class="muted">Text stays editable. Regenerate art after changing the scene or cast.</p>${p.genError&&!p.imageId?`<p class="error-note">${esc(p.genError)}</p>`:''}${button(p.imageId?'↻ Regenerate this panel':'✦ Generate this panel','generate-panel','',`data-id="${p.id}" data-ai`)}${p.imageId?button('Speech bubbles','edit-bubbles','secondary',`data-id="${p.id}"`):''}${p.cast.filter(i=>lib.characters.find(c=>c.id===i)?.refId).length>1?'<p class="muted">Local face conditioning uses the first character reference only.</p>':''}</div></article>`;}
function panelsView(){const e=episode();const panels=allPanels(e);const done=panels.filter(p=>p.imageId).length;const resume=resumeLabel();return `<div class="toolbar">${button('✦ AI plan pages','plan','','data-ai')}${button(`✦ Generate ${panelCount()}-panel comic`,'generate-comic','','data-ai')}${resume?button(resume,'resume-comic','secondary','data-ai'):''}${button('＋ Blank page','add-page','secondary','data-mutates')}${button('Read episode','read','secondary')}</div><p class="muted">${panels.length?`${done}/${panels.length} panels illustrated. `:''}Generate one panel, or the whole comic in order. Cancel anytime and resume without redoing finished art.</p><datalist id="cameraAngles"><option value="Wide establishing shot"><option value="Medium shot, eye level"><option value="Close-up, three-quarter view"><option value="Over the shoulder"><option value="Low angle"><option value="Bird’s-eye view"></datalist>${e.pages.length?e.pages.map((p,i)=>`<section class="card"><div class="row between"><h2>Page ${i+1}</h2><label style="margin:0">Layout<select data-page-layout="${p.id}" aria-label="Page ${i+1} layout"><option value="single" ${p.layout==='single'?'selected':''}>Single column</option><option value="two" ${p.layout==='two'?'selected':''}>Two columns</option><option value="hero" ${p.layout==='hero'?'selected':''}>Hero + grid</option></select></label></div><div class="panel-list" style="margin-top:16px">${p.panels.map(panelCard).join('')}</div><div class="row">${button('＋ Add panel','add-panel','secondary small',`data-id="${p.id}" data-mutates`)}${button('Remove page','remove-page','ghost small',`data-id="${p.id}" data-mutates`)}</div></section>`).join(''):'<div class="empty"><h3>From words to frames.</h3><p>Plan pages from your script, or add a blank page to build your own layout.</p></div>'}<p class="save-status status-line">Saved on this device · back up regularly</p>`;}
function settingsView(){return `<p class="eyebrow">Your studio, your rules</p><h1>Settings</h1><form id="settingsForm"><section class="card"><h2>Connections</h2><label class="check"><input name="demo" type="checkbox" ${settings.demo?'checked':''}>Offline demo mode · no API calls</label><p class="muted">Turn off only when you’re ready to use your own services. No paid requests are sent without a confirmation.</p>${input('Panels per auto-generated comic','panelCount',panelCount(),'number','min="1" max="72" step="1"')}<p class="muted">Generate comic splits the script into this many panels, 45 by default, then illustrates them in order.</p>${input('Venice API key','veniceKey',localStorage.getItem('cs_k')||'','password','autocomplete="off" spellcheck="false"')}<p class="muted">Stored only in this browser, never in backups. It is not encrypted; use a trusted device and host.</p>${input('Local image server URL · optional','localURL',settings.localURL,'url','placeholder="https://your-private-tunnel.example" autocomplete="off"')}${input('Local server bearer token · optional, separate from Venice','localKey',localStorage.getItem('cs_local_k')||'','password','autocomplete="off" spellcheck="false"')}<p class="muted">Your PC must be on. The phone needs a reachable HTTPS endpoint with CORS enabled. The Venice key is never sent to your local server.</p><label class="check"><input name="allowCloudFallback" type="checkbox" ${settings.allowCloudFallback?'checked':''}>Offer Venice fallback if local rendering fails</label><p class="muted">Local is preferred whenever set. Fallback is off by default and still asks before spending.</p></section><section class="card"><h2>Models</h2>${input('Text model · default_vision trait follows Venice’s current default','textModel',settings.textModel,'text','list="textModels" maxlength="150"')}${input('Image model · Chroma has a Lustify-SDXL fallback','imageModel',settings.imageModel,'text','list="imageModels" maxlength="150"')}<datalist id="textModels">${pickerModels(provider.models,'text').map(m=>`<option value="${esc(m.id)}">${esc(modelLabel(m))}</option>`).join('')}</datalist><datalist id="imageModels">${pickerModels(provider.models,'image').map(m=>`<option value="${esc(m.id)}">${esc(modelLabel(m))}</option>`).join('')}</datalist><div class="row"><button type="submit">Save settings</button>${button('Load available models','load-models','secondary','data-ai')}</div><p class="muted" id="modelsStatus">${provider.models.length?`${provider.models.length} active models loaded. Deprecated models excluded.`:'Model discovery runs only when you ask. Save settings before loading.'}</p></section></form><section class="card"><h2>Library backup</h2><p class="muted">Characters, reference art, scripts, layouts, and panel art in one JSON file. Keys and connection settings are excluded. Keep backups private: they contain your stories and images.</p><div class="row">${button('↓ Export library','export','','data-mutates')}${button('↑ Import backup','import','secondary','data-mutates')}</div><input type="file" id="importFile" accept="application/json,.json" hidden><p class="muted" style="margin-top:12px">Import replaces this device’s library after confirmation. Export first if you want to keep it.</p></section><section class="card"><h2>Privacy & content</h2><p class="muted">Your library stays in IndexedDB on this device. It isn’t a synced account or encrypted vault. Other people using this browser profile can open it. Clearing website data deletes it.</p><p class="muted">AI writing sends selected character profiles and your episode to Venice. Image generation sends the scene prompt and supported reference art to the chosen provider. No auto-illustration, analytics, or background paid tasks.</p><p class="settings-warning">Fictional adults 18+ only. Explicit adult content and nudity between consenting fictional adults is allowed. Minors, age ambiguity, real identifiable people, bestiality, and non-consent are blocked. Venice image requests use safe_mode: false, and uncensored models are listed first.</p><p class="muted">Client-side content checks are a guardrail, not tamper-proof moderation. A hosted production API also needs server-side checks.</p></section><section class="card"><h2>Put it on your home screen</h2><p class="muted">Open the HTTPS-hosted app in Safari, tap Share, then Add to Home Screen. The interface and existing library work offline. AI needs internet or your reachable local server.</p>${button('Request persistent device storage','persist-storage','secondary')}<p class="muted" id="storageStatus">Browser storage is best-effort. Keep exported backups even with persistence.</p></section><p class="status-line">Comic Studio v1.2 · local-first · no account needed</p>`;}
function seriesForm(existing){const s=existing||{title:'',synopsis:'',style:STYLE};showModal(`<form id="seriesForm" data-id="${existing?.id||''}"><div class="modal-title"><h2>${existing?'Series settings':'Start a new series'}</h2>${button('✕','close','ghost','aria-label="Close"')}</div>${input('Series title','title',s.title,'text','required maxlength="200" placeholder="The world you’re about to create"')}${area('Premise / synopsis','synopsis',s.synopsis,'maxlength="5000"')}${area('Art style · used in every panel','style',s.style,'required maxlength="5000"')}<p class="muted">Default: stylized 3D toon faces with realistic skin, lighting, and tattoo detail. Change it for this series only.</p><div class="sticky-actions">${button('Cancel','close','secondary')}<button type="submit">${existing?'Save series':'Create series'}</button></div></form>`);}
function episodeForm(){showModal(`<form id="episodeForm"><div class="modal-title"><h2>A new chapter</h2>${button('✕','close','ghost','aria-label="Close"')}</div>${input('Episode title','title','','text','required maxlength="200" placeholder="Episode '+(series().episodes.length+1)+'"')}<p class="muted">You can write the script and select characters on the next screen.</p><div class="sticky-actions">${button('Cancel','close','secondary')}<button type="submit">Create episode</button></div></form>`);}
function characterForm(c){draft=structuredClone(c||{id:uid(),name:'',age:30,fictional:false,description:'',personality:'',backstory:'',body:'',hair:'',outfit:'',tattoos:'',refId:null});drawCharacterForm();}
function drawCharacterForm(){const c=draft;showModal(`<form id="characterForm"><div class="modal-title"><h2>${lib.characters.some(x=>x.id===c.id)?'Edit character':'Meet someone new'}</h2>${button('✕','close','ghost','aria-label="Close"')}</div><div class="row"><div class="grow">${input('Name','name',c.name,'text','required maxlength="100"')}</div><div style="width:100px">${input('Age · 18+','age',c.age,'number','required min="18" max="150" step="1"')}</div></div><label class="check"><input name="fictional" type="checkbox" ${c.fictional?'checked':''} required>This is a fictional adult, age 18 or older. Uploaded art depicts only fictional adults.</label>${area('Appearance / visual description','description',c.description,'required maxlength="8000" placeholder="Distinctive face, eyes, build, colors, and other details…"')}<details><summary>Quick appearance presets</summary><label>Starting look<select id="appearancePreset"><option value="">Choose a preset…</option><option value="explorer">Cinematic explorer</option><option value="noir">Neon noir detective</option><option value="artist">Off-duty artist</option></select></label>${input('Body / build','body',c.body,'text','maxlength="1000"')}${input('Hair','hair',c.hair,'text','maxlength="1000"')}${input('Outfit','outfit',c.outfit,'text','maxlength="1000"')}${input('Tattoos / markings','tattoos',c.tattoos,'text','maxlength="2000"')}</details>${area('Personality / voice','personality',c.personality,'maxlength="8000" placeholder="What are they like? How do they speak?"')}${area('Backstory / relationships','backstory',c.backstory,'maxlength="8000" placeholder="Their history, motives, and relationships…"')}<hr><h3>Identity reference</h3><p class="muted">Upload fictional character art or a front / side / back turnaround. Multi-view sheets are saved as one identity reference.</p>${refMarkup(c.refId)}<label>Upload reference art<input id="referenceFile" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="muted">JPEG, PNG, or WebP up to 20 MB. Images are resized to 1536 px. Do not upload real-person likenesses.</p><div class="row">${button('✦ Generate reference sheet','generate-reference','secondary','data-ai')}${c.refId?button('Remove reference','remove-reference','ghost','data-mutates'):''}</div><p class="help">Reference sheets guide the look; exact face and tattoo continuity is not guaranteed. A local FaceID server can condition one face. Some Venice models accept style references after model discovery.</p><div class="sticky-actions">${button('Cancel','close','secondary')}<button type="submit" data-mutates>Save character</button></div></form>`);setBusy(busy);}
function collectCharacter(){const f=new FormData($('#characterForm'));const c={...draft,age:Number(f.get('age')),fictional:f.has('fictional')};for(const k of ['name','description','personality','backstory','body','hair','outfit','tattoos'])c[k]=String(f.get(k)||'').trim();return c;}
function requireStory(){const e=episode();if(!e.script.trim())throw Error('Write your episode first.');const chars=selectedCharacters();if(!chars.length)throw Error('Choose at least one fictional adult character for the episode.');assertSafe([series().title,series().synopsis,series().style,e.title,e.script,...chars.map(characterText)].join('\n'),chars);return chars;}
async function polish(){const chars=requireStory(),e=episode();const result=await provider.text('polish',{title:e.title,script:e.script,series:series().synopsis,characters:chars.map(c=>({id:c.id,profile:characterText(c)}))},chars);showModal(`<div class="modal-title"><h2>Review the polish</h2>${button('✕','close','ghost','aria-label="Close"')}</div><p class="muted">Your original stays untouched until you apply this version.</p><label>Proposed script<textarea id="polishResult" rows="17" maxlength="60000">${esc(result)}</textarea></label><div class="sticky-actions">${button('Keep original','close','secondary')}${button('Apply polish','apply-polish','')}</div>`);}
async function plan(){const chars=requireStory(),e=episode();if(e.pages.length&&!await ask('Replace this storyboard?','New AI planning replaces these pages and their panel art. Your script stays unchanged. Export a backup first to keep the current version.','Replace pages'))return;const raw=await provider.text('plan',{title:e.title,script:e.script,style:series().style,series:series().synopsis,cast:chars.map(c=>({id:c.id,name:c.name,profile:characterText(c)}))},chars);const pages=normalizePlan(raw,chars.map(c=>c.id));e.pages=pages;await save();tab='panels';render();notify('Storyboard ready. Edit every detail before generating art.');}
async function generatePanel(id){const p=panelById(id);if(!p)throw Error('Panel not found.');const chars=selectedCharacters(p.cast);if(!chars.length)throw Error('Choose at least one fictional adult character for this panel.');const scene=p.prompt.trim();if(!scene)throw Error('Add a scene prompt first.');const all=[series().style,series().synopsis,episode().script,scene,p.camera,p.dialogue,p.caption,...chars.map(characterText)].join('\n');assertSafe(all,chars);const job=panelJob({...p,prompt:scene},chars,series().style);const blob=await provider.image(job.prompt,job.referenceIds,chars);p.imageId=await putAsset(blob);p.genError=undefined;await save();render();notify(settings.demo?'Demo panel created locally. No credits used.':'Panel saved on this device.');}
function showBatch(completed,total,note=''){const el=$('#batchStatus');if(!el)return;el.hidden=false;$('#batchCount').textContent=`${completed}/${total}`;const bar=$('#batchProgress');bar.max=String(total||1);bar.value=String(completed);$('#batchNote').textContent=note||'';}
function hideBatch(){const el=$('#batchStatus');if(el)el.hidden=true;}
function paintPanel(p){document.querySelectorAll(`[data-preview="${p.id}"]`).forEach(node=>{node.innerHTML=preview(p,{edit:!!node.closest('#reader')});hydrate(node);});}
async function generateComic(resume){try{if(resume){if(!allPanels().length)throw Error('Generate the comic first, then resume any panels that do not have art yet.');await illustrateEpisode();return;}const chars=requireStory();const e=episode();const count=panelCount();const existing=allPanels().length;if(existing&&!await ask('Replace this storyboard?',`This splits your script into ${count} panels and illustrates each one in order. The current ${existing} panel${existing===1?'':'s'} and their art will be replaced. Your script stays as it is.`,'Replace and generate'))return;showBatch(0,count,'Planning panels from your script…');let plan=null;try{plan=await provider.text('plan',{title:e.title,script:e.script,style:series().style,series:series().synopsis,cast:chars.map(c=>({id:c.id,name:c.name,profile:characterText(c)})),targetPanels:count},chars);}catch(err){if(isCancelled(err))throw err;plan=null;notify('Planning used a local beat split. '+(err.message||''));}e.pages=buildEpisodePages({script:e.script,cast:chars.map(c=>c.id),count,plan});await save();tab='panels';render();await illustrateEpisode();}finally{if(!batchAbort)hideBatch();}}
async function illustrateEpisode(){const e=episode();const panels=allPanels(e);const pending=panels.filter(p=>!p.imageId);if(!pending.length){notify('Every panel already has art.');return;}if(!settings.demo){if(!settings.localURL&&!localStorage.getItem('cs_k'))throw Error('Add a Venice API key or a local image server before generating panels.');const where=settings.localURL?'your local image server':'Venice';if(!await ask('Generate panel images?',`${pending.length} image request${pending.length===1?'':'s'} will run one at a time on ${where}. Saved character references are reused for every panel. Finished panels are kept if you cancel or a later panel fails.`,'Start images')){notify(`Image generation cancelled. ${panels.length-pending.length}/${panels.length} panels already have art. Resume to continue.`);return;}}tab='panels';if(!document.querySelector(`[data-preview="${panels[0]?.id||''}"]`))render();batchAbort=new AbortController();const signal=batchAbort.signal;showBatch(panels.length-pending.length,panels.length,'Starting…');try{const result=await runPanelBatch({panels,shouldCancel:()=>signal.aborted,generate:async p=>{const chars=selectedCharacters(p.cast);if(!chars.length)throw Error('Choose at least one fictional adult character for this panel.');const scene=(p.prompt||'').trim();if(!scene)throw Error('This panel has no scene prompt.');assertSafe([series().style,series().synopsis,e.script,scene,p.camera,p.dialogue,p.caption,...chars.map(characterText)].join('\n'),chars);const job=panelJob({...p,prompt:scene},chars,series().style);return provider.image(job.prompt,job.referenceIds,chars,{signal,approved:true});},save:async(panel,blob)=>{const imageId=await putAsset(blob);panel.imageId=imageId;panel.genError=undefined;await save();paintPanel(panel);return imageId;},onProgress:({completed,total,state,error})=>{const note=state==='failed'?(error||'A panel failed. Resume will retry it.'):state==='panel'?'Rendering the next panel…':'';showBatch(completed,total,note);}});const done=result.completed;if(result.cancelled)notify(`Stopped at ${done}/${result.total}. Resume to continue without redoing finished panels.`);else if(result.failed)notify(`${done}/${result.total} panels saved. ${result.failed} failed — Resume retries only those.`);else notify(settings.demo?`Demo comic ready, ${done}/${result.total} panels, no credits used.`:`Comic saved on this device, ${done}/${result.total} panels.`);}finally{batchAbort=null;hideBatch();render();}}
function syncBubbles(){if(!lettering)return;const panel=panelById(lettering.panelId);if(!panel)return;panel.bubbles=lettering.bubbles.map(b=>({...b}));queueSave();document.querySelectorAll(`[data-preview="${panel.id}"]`).forEach(node=>{if(node.closest('#lettering'))return;node.innerHTML=preview(panel,{edit:!!node.closest('#reader')});hydrate(node);});}
function markBubbleSelection(){document.querySelectorAll('#lettering [data-bubble-id]').forEach(n=>n.classList.toggle('selected',n.dataset.bubbleId===lettering?.selected));const selected=lettering?.bubbles.find(b=>b.id===lettering.selected);const font=document.querySelector('[data-bubble-font]');const flip=document.querySelector('[data-action="flip-tail"]');const del=document.querySelector('[data-action="delete-bubble"]');if(font){font.disabled=!selected;if(selected)font.value=String(selected.fontSize);}if(flip)flip.disabled=!selected;if(del)del.disabled=!selected;}
function drawBubbleEditor(){const panel=panelById(lettering.panelId);const presets=BUBBLE_PRESETS.map(p=>`<button type="button" class="preset" data-action="add-bubble" data-preset="${esc(p.id)}"><img alt="" src="${esc(p.src)}"><span>${esc(p.name)}</span></button>`).join('');const selected=lettering.bubbles.find(b=>b.id===lettering.selected);$('#letteringContent').innerHTML=`<div class="lettering-top"><div><p class="eyebrow" style="margin:0">Lettering</p><strong>Speech bubbles</strong></div>${button('Done','close-lettering','')}</div><div class="bubble-stage" data-bubble-stage><img class="panel-photo" data-image-id="${esc(panel.imageId)}" alt="Comic panel">${renderLettering(lettering.bubbles,{interactive:true,selected:lettering.selected})}</div><div class="preset-row" role="list">${presets}</div><div class="row bubble-tools"><label class="grow">Font size<input type="range" min="0.02" max="0.12" step="0.002" value="${selected?.fontSize??0.042}" data-bubble-font ${selected?'':'disabled'}></label>${button('Flip tail','flip-tail','secondary',selected?'':'disabled')}${button('Delete','delete-bubble','danger',selected?'':'disabled')}</div><p class="muted">Drag the bubble or the ✥ handle to place it. Drag the teal dot to aim the tail, and the corner to resize. Tap the words to type. Touch works the same as a mouse.</p>`;hydrate($('#lettering'));bindBubbleStage($('#lettering [data-bubble-stage]'));}
function bindBubbleStage(stage){if(!stage)return;const point=e=>{const r=stage.getBoundingClientRect();return {x:(e.clientX-r.left)/Math.max(1,r.width),y:(e.clientY-r.top)/Math.max(1,r.height)};};stage.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-handle]');const node=e.target.closest('[data-bubble-id]');if(e.target.closest('textarea')){if(node){lettering.selected=node.dataset.bubbleId;markBubbleSelection();}return;}if(!node){lettering.selected=null;markBubbleSelection();return;}e.preventDefault();const id=node.dataset.bubbleId;lettering.selected=id;markBubbleSelection();const b=lettering.bubbles.find(x=>x.id===id);bubbleGesture={id,pointer:e.pointerId,mode:handle?.dataset.handle||'move',start:point(e),orig:{...b},moved:false,clientX:e.clientX,clientY:e.clientY,node};try{stage.setPointerCapture(e.pointerId);}catch{/* iOS still delivers the pointer events without capture */}},{passive:false});stage.addEventListener('pointermove',e=>{if(!bubbleGesture||e.pointerId!==bubbleGesture.pointer)return;if(Math.hypot(e.clientX-bubbleGesture.clientX,e.clientY-bubbleGesture.clientY)>8)bubbleGesture.moved=true;if(bubbleGesture.mode==='move'&&!bubbleGesture.moved)return;e.preventDefault();const next=dragUpdate(bubbleGesture.mode==='move'?'move':bubbleGesture.mode,bubbleGesture.orig,bubbleGesture.start,point(e));const b=lettering.bubbles.find(x=>x.id===bubbleGesture.id);Object.assign(b,next);applyBubbleElement(bubbleGesture.node,b);const svg=stage.querySelector('.tail-layer');if(svg)svg.innerHTML=lettering.bubbles.map(tailMarkup).join('');},{passive:false});stage.addEventListener('pointerup',e=>{if(!bubbleGesture||e.pointerId!==bubbleGesture.pointer)return;const g=bubbleGesture;bubbleGesture=null;if(!g.moved&&(g.mode==='move'))g.node.querySelector('textarea')?.focus();else syncBubbles();});stage.addEventListener('pointercancel',()=>{if(bubbleGesture){bubbleGesture=null;syncBubbles();}});}
function openBubbleEditor(id){const panel=panelById(id);if(!panel?.imageId){notify('Generate the panel image before adding speech bubbles.');return;}lettering={panelId:id,selected:null,bubbles:seedBubbles(panel).map(b=>({...b}))};lettering.selected=lettering.bubbles[0]?.id||null;drawBubbleEditor();const dialog=$('#lettering');if(!dialog.open)dialog.showModal();}
async function closeLettering(){if(!lettering)return;for(const b of lettering.bubbles)assertSafe(b.text||'');syncBubbles();await flush();lettering=null;bubbleGesture=null;const dialog=$('#lettering');if(dialog?.open)dialog.close();render();}
function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Could not draw that panel.'));img.src=src;});}
async function downloadReaderPage(){const e=episode();const page=e?.pages?.[readerIndex];if(!page)return;const images=new Map();await Promise.all(BUBBLE_PRESETS.map(async preset=>{try{images.set(preset.id,await loadImage(preset.src));}catch{/* fallback shape */}}));const cellW=800,cellH=1000,gap=14,cols=page.layout==='single'?1:2,hero=page.layout==='hero'&&page.panels.length>1;const boxes=[];let cursor=gap,width=gap+cols*cellW+(cols-1)*gap+gap;if(hero){const span=cols*cellW+(cols-1)*gap;boxes.push({panel:page.panels[0],x:gap,y:cursor,w:span,h:Math.round(cellH*0.72)});cursor+=Math.round(cellH*0.72)+gap;page.panels.slice(1).forEach((panel,i)=>{const col=i%cols,row=Math.floor(i/cols);boxes.push({panel,x:gap+col*(cellW+gap),y:cursor+row*(cellH+gap),w:cellW,h:cellH});});const rows=Math.ceil((page.panels.length-1)/cols)||0;var height=cursor+(rows?rows*cellH+(rows-1)*gap:0)+gap;}else{page.panels.forEach((panel,i)=>{const col=i%cols,row=Math.floor(i/cols);boxes.push({panel,x:gap+col*(cellW+gap),y:gap+row*(cellH+gap),w:cellW,h:cellH});});const rows=Math.ceil(page.panels.length/cols)||1;var height=gap+rows*cellH+(rows-1)*gap+gap;}const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const draw=async(useImages)=>{const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,width,height);for(const box of boxes){ctx.save();ctx.beginPath();ctx.rect(box.x,box.y,box.w,box.h);ctx.clip();ctx.fillStyle='#fbe3ec';ctx.fillRect(box.x,box.y,box.w,box.h);if(box.panel.imageId){const url=await assetURL(box.panel.imageId);if(url){const img=await loadImage(url);const cover=coverRect(img.naturalWidth||img.width,img.naturalHeight||img.height,box.w,box.h);ctx.drawImage(img,box.x+cover.x,box.y+cover.y,cover.w,cover.h);}}if(box.panel.bubbles?.length)paintBubbles(ctx,{x:box.x,y:box.y,w:box.w,h:box.h},box.panel.bubbles,useImages?images:new Map());else paintLegacyLettering(ctx,box);ctx.restore();}};await draw(true);let blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob){await draw(false);blob=await new Promise((r,j)=>canvas.toBlob(b=>b?r(b):j(Error('Could not export this page.')),'image/png'));}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`comic-page-${readerIndex+1}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Page download started. Bubbles are drawn on top of the art.');}
function paintLegacyLettering(ctx,box){const lines=(box.panel.dialogue||'').split('\n').map(s=>s.trim()).filter(Boolean).slice(0,4);ctx.fillStyle='#fffaf7';ctx.strokeStyle='#352832';ctx.lineWidth=3;ctx.font='600 28px Georgia, serif';ctx.textAlign='left';ctx.textBaseline='top';let y=box.panel.bubblePosition==='bottom'?box.y+box.h-36-lines.length*40:box.y+16;for(const line of lines){const text=line.replace(/^([^:]{1,40}):\s+/,'$1: ');ctx.fillRect(box.x+16,y,Math.min(box.w-32,ctx.measureText(text).width+28),36);ctx.strokeRect(box.x+16,y,Math.min(box.w-32,ctx.measureText(text).width+28),36);ctx.fillStyle='#352832';ctx.fillText(text,box.x+28,y+6,box.w-64);ctx.fillStyle='#fffaf7';y+=40;}if(box.panel.caption){ctx.fillStyle='#ddf4f0';ctx.fillRect(box.x+12,box.y+box.h-52,box.w-24,40);ctx.fillStyle='#155b5b';ctx.font='600 22px system-ui, sans-serif';ctx.fillText(box.panel.caption,box.x+24,box.y+box.h-42,box.w-48);}}
async function generateReference(){draft=collectCharacter();validateCharacter(draft);const prompt=`${STYLE}\nCharacter design turnaround sheet on a plain studio background: front, side profile, and back views of the SAME fictional adult. No text or labels. Consistent facial features, adult proportions, hair, and tattoo placement across all three views. Outfit or nudity follows the character description and request, and every depicted person is a fictional adult, age 18+.\n${characterText(draft)}`;const blob=await provider.image(prompt,draft.refId?[draft.refId]:[],[draft]);draft.refId=await putAsset(blob);drawCharacterForm();notify('Reference ready. Save the character to keep it in your cast.');}
function openReader(){if(!episode()?.pages.length){notify('Plan or add at least one page before opening the reader.');return;}readerIndex=0;drawReader();$('#reader').showModal();}
function drawReader(){const e=episode(),p=e.pages[readerIndex];$('#readerContent').innerHTML=`<div class="reader-toolbar"><div><p class="eyebrow" style="margin:0">${esc(series().title)}</p><strong>${esc(e.title)}</strong></div><div class="row">${button('↓ Page','download-page','secondary')}${button('✕','close-reader','secondary','aria-label="Close reader"')}</div></div><div class="comic-page ${p.layout}" id="swipePage">${p.panels.map(x=>`<div class="panel-art" data-preview="${x.id}">${preview(x,{edit:true})}</div>`).join('')}</div><div class="reader-controls">${button('← Previous','prev-page','secondary',readerIndex===0?'disabled':'')}<span class="muted" aria-live="polite">Page ${readerIndex+1} / ${e.pages.length}</span>${button('Next →','next-page','secondary',readerIndex===e.pages.length-1?'disabled':'')}</div><p class="reader-note">Swipe left / right to turn pages · Bubbles opens the lettering editor · Page downloads the art with bubbles on top</p>`;hydrate($('#reader'));}
function moveReader(delta){const n=readerIndex+delta;if(n>=0&&n<episode().pages.length){readerIndex=n;drawReader();$('#reader').scrollTop=0;}}
function sample(){if(lib.characters.length>98||lib.series.length>=100)throw Error('Library limit reached.');const a={id:uid(),name:'Mira Vale',age:32,fictional:true,description:'An expressive adult woman with warm brown skin, amber eyes, and a silver eyebrow piercing.',personality:'Fearless, wry, quietly affectionate. Speaks in short, warm observations.',backstory:'A cartographer who maps abandoned orbital gardens with her partner.',body:'Athletic adult build',hair:'Dark curls in a loose bun',outfit:'Copper flight jacket, navy trousers, and practical boots',tattoos:'Fine geometric constellation on the left forearm',refId:null};const b={...a,id:uid(),name:'Rowan Ash',age:35,description:'A broad-shouldered adult man with olive skin, green eyes, and a neatly trimmed beard.',personality:'Patient, curious, dry humor.',backstory:'A former botanical engineer and Mira’s partner.',hair:'Short wavy black hair',outfit:'A charcoal field coat over a moss-green shirt',tattoos:'An abstract leaf pattern on the right wrist'};lib.characters.push(a,b);const e={id:uid(),title:'The garden above the clouds',script:'The last shuttle leaves Mira and Rowan at the edge of an abandoned orbital garden. Amber light spills through the glass canopy.\n\nMira unfolds a paper map. “You said this place was empty.” Rowan smiles at the wildflowers growing through the floor. “I said nobody lived here.”\n\nThey find a bench overlooking the blue planet. Mira leans against Rowan’s shoulder. For the first time all week, neither of them has anywhere else to be.',previousScript:'',cast:[a.id,b.id],pages:[]};const s={id:uid(),title:'After the Last Shuttle',synopsis:'Two grown-up explorers finding extraordinary places, and a little more time for each other.',style:STYLE,episodes:[e]};lib.series.push(s);sid=s.id;eid=e.id;tab='write';save();render();notify('Sample loaded. Try AI polish, then Plan pages — demo mode uses no API.');}
async function exportBackup(){await flush();const backup=await exportLibrary(lib);const blob=new Blob([JSON.stringify(backup)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`comic-studio-${new Date().toLocaleDateString('en-CA')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Backup download started. Save it somewhere private. API keys were excluded.');}
async function importBackup(file){if(!file)return;if(file.size>100*1024*1024)throw Error('Backups over 100 MB are not supported in v1.');let raw;try{raw=JSON.parse(await file.text());}catch{throw Error('That file is not valid JSON.');}if(!await ask('Replace your library?',`Import “${file.name}” and replace all characters, episodes, and images on this device? Connection settings stay unchanged. Export first if you need a copy.`,'Replace library'))return;await flush();lib=await importLibrary(raw);for(const u of assetURLs.values())URL.revokeObjectURL(u);assetURLs.clear();sid=eid=null;nav='library';render();notify('Library restored. Keys and connection settings were not imported.');}
const actions={
  close:()=>closeModal(),
  'new-series':()=>{if(lib.series.length>=100)throw Error('V1 supports up to 100 series.');seriesForm();},
  'edit-series':()=>seriesForm(series()),
  'open-series':b=>{sid=b.dataset.id;eid=null;render();window.scrollTo(0,0);},
  'back-library':()=>{sid=eid=null;render();},
  'back-series':()=>{eid=null;render();},
  'new-episode':()=>{if(series().episodes.length>=200)throw Error('V1 supports up to 200 episodes per series.');episodeForm();},
  'open-episode':b=>{eid=b.dataset.id;tab='write';render();window.scrollTo(0,0);},
  'new-character':()=>{if(lib.characters.length>=100)throw Error('V1 supports up to 100 characters.');characterForm();},
  'edit-character':b=>characterForm(lib.characters.find(c=>c.id===b.dataset.id)),
  'remove-reference':()=>{draft=collectCharacter();draft.refId=null;drawCharacterForm();},
  'generate-reference':()=>run(generateReference),
  polish:()=>run(polish),plan:()=>run(plan),
  'generate-comic':()=>run(()=>generateComic(false)),
  'resume-comic':()=>run(()=>generateComic(true)),
  'cancel-batch':()=>{if(batchAbort)batchAbort.abort();},
  'edit-bubbles':b=>openBubbleEditor(b.dataset.id),
  'add-bubble':b=>{if(!lettering)return;const count=lettering.bubbles.length;const bubble=createBubble(b.dataset.preset,{x:0.08+(count%3)*0.06,y:0.06+(count%4)*0.1});lettering.bubbles.push(bubble);lettering.selected=bubble.id;drawBubbleEditor();syncBubbles();},
  'flip-tail':()=>{if(!lettering)return;const b=lettering.bubbles.find(x=>x.id===lettering.selected);if(!b)return;Object.assign(b,flipTail(b));drawBubbleEditor();syncBubbles();},
  'delete-bubble':()=>{if(!lettering)return;lettering.bubbles=lettering.bubbles.filter(b=>b.id!==lettering.selected);lettering.selected=lettering.bubbles.at(-1)?.id||null;drawBubbleEditor();syncBubbles();},
  'close-lettering':()=>closeLettering(),
  'download-page':()=>run(downloadReaderPage),
  'apply-polish':async()=>{const e=episode(),value=$('#polishResult').value;assertSafe(value,selectedCharacters());e.previousScript=e.script;e.script=value;await save();closeModal();render();notify('Polish applied. Your previous draft is available with Undo last polish.');},
  'undo-polish':async()=>{const e=episode();[e.script,e.previousScript]=[e.previousScript,e.script];await save();render();},
  'generate-panel':b=>run(()=>generatePanel(b.dataset.id)),
  'add-page':async()=>{const e=episode();const count=e.pages.reduce((n,p)=>n+p.panels.length,0);if(e.pages.length>=EPISODE_MAX_PAGES||count>=EPISODE_MAX_PANELS)throw Error(`Episode limit: ${EPISODE_MAX_PAGES} pages / ${EPISODE_MAX_PANELS} panels.`);e.pages.push({id:uid(),layout:'two',panels:[newPanel(e.cast)]});await save();render();},
  'add-panel':async b=>{const e=episode(),p=e.pages.find(p=>p.id===b.dataset.id);const count=e.pages.reduce((n,p)=>n+p.panels.length,0);if(p.panels.length>=PAGE_MAX_PANELS||count>=EPISODE_MAX_PANELS)throw Error(`Limit: ${PAGE_MAX_PANELS} panels per page / ${EPISODE_MAX_PANELS} per episode.`);p.panels.push(newPanel(e.cast));await save();render();},
  'remove-panel':async b=>{if(!await ask('Remove panel?','Its lettering and artwork will be removed from this storyboard.','Remove'))return;const e=episode(),p=e.pages.find(p=>p.panels.some(x=>x.id===b.dataset.id));p.panels=p.panels.filter(x=>x.id!==b.dataset.id);e.pages=e.pages.filter(p=>p.panels.length);await save();render();},
  'remove-page':async b=>{if(!await ask('Remove this page?','All its panels, lettering, and artwork will leave the storyboard.','Remove'))return;episode().pages=episode().pages.filter(p=>p.id!==b.dataset.id);await save();render();},
  read:()=>openReader(),'close-reader':()=>$('#reader').close(),'prev-page':()=>moveReader(-1),'next-page':()=>moveReader(1),
  sample:()=>sample(),export:()=>run(exportBackup),import:()=>$('#importFile').click(),
  'load-models':()=>run(async()=>{await provider.loadModels();render();notify(`${provider.models.length} active models loaded. Save a model choice in Settings.`);}),
  'persist-storage':async()=>{const granted=await navigator.storage?.persist?.();$('#storageStatus').textContent=granted?'Persistent storage granted. Still keep backups.':'The browser did not grant persistent storage. Export backups regularly.';}
};
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(busy&&!['close-reader','prev-page','next-page','cancel-batch'].includes(b.dataset.action))return;if(b.dataset.nav){if(busy)return;await flush().catch(()=>{});nav=b.dataset.nav;sid=eid=null;render();window.scrollTo(0,0);return;}if(b.dataset.tab){if(busy)return;await flush().catch(()=>{});tab=b.dataset.tab;render();return;}const fn=actions[b.dataset.action];if(fn){try{await fn(b);}catch(e){notify(e.message,true);}}});
$('#brand').addEventListener('click',async e=>{e.preventDefault();if(busy)return;await flush().catch(()=>{});nav='library';sid=eid=null;render();});
document.addEventListener('submit',async ev=>{ev.preventDefault();if(busy)return;const form=ev.target;try{
  if(form.id==='seriesForm'){const f=new FormData(form);const title=String(f.get('title')).trim(),synopsis=String(f.get('synopsis')).trim(),style=String(f.get('style')).trim();if(!title||!style)throw Error('Add a title and art style.');assertSafe([title,synopsis,style].join('\n'));let s=lib.series.find(s=>s.id===form.dataset.id);if(s)Object.assign(s,{title,synopsis,style});else{s={id:uid(),title,synopsis,style,episodes:[]};lib.series.push(s);}await save();closeModal();nav='library';sid=s.id;eid=null;render();}
  if(form.id==='episodeForm'){const f=new FormData(form),title=String(f.get('title')).trim();assertSafe(title);if(!title)throw Error('Add an episode title.');const e={id:uid(),title,script:'',previousScript:'',cast:lib.characters.map(c=>c.id),pages:[]};series().episodes.push(e);await save();closeModal();eid=e.id;tab='write';render();}
  if(form.id==='characterForm'){const c=collectCharacter();validateCharacter(c);const i=lib.characters.findIndex(x=>x.id===c.id);if(i>=0)lib.characters[i]=c;else lib.characters.push(c);await save();closeModal();render();notify('Character saved. Their full profile will guide your stories.');}
  if(form.id==='settingsForm'){const f=new FormData(form);const localURL=localBase(String(f.get('localURL')).trim());const next={demo:f.has('demo'),localURL,allowCloudFallback:f.has('allowCloudFallback'),textModel:String(f.get('textModel')).trim()||'default_vision',imageModel:String(f.get('imageModel')).trim()||'chroma',panelCount:clampPanelCount(f.get('panelCount'))};if(!next.demo&&settings.demo&&!await ask('Enable live requests?','This mode connects to your selected providers. Each Venice generation asks before spending. Prompts and supported reference images leave this device.','Enable live mode'))return;settings=next;provider.settings=settings;writeSettings(settings);for(const [key,field] of [['cs_k','veniceKey'],['cs_local_k','localKey']]){const v=String(f.get(field)||'').trim();v?localStorage.setItem(key,v):localStorage.removeItem(key);}render();notify('Settings saved on this device.');}
}catch(e){notify(e.message,true);}});
document.addEventListener('input',ev=>{const n=ev.target;const e=episode();if(n.dataset.bind==='script'&&e){e.script=n.value;queueSave();}if(n.dataset.bind==='episode-title'&&e){e.title=n.value;queueSave();}if(n.dataset.bubbleText&&lettering){const b=lettering.bubbles.find(x=>x.id===n.dataset.bubbleText);if(!b)return;const next=n.value.slice(0,500);try{assertSafe(next);b.text=next;syncBubbles();}catch(err){n.value=b.text||'';notify(err.message,true);}return;}if(n.dataset.bubbleFont&&lettering){const b=lettering.bubbles.find(x=>x.id===lettering.selected);if(!b)return;Object.assign(b,setFontSize(b,n.value));const node=document.querySelector(`#lettering [data-bubble-id="${b.id}"]`);if(node)applyBubbleElement(node,b);syncBubbles();return;}if(n.dataset.panelField){const p=panelById(n.dataset.id);if(!p)return;p[n.dataset.panelField]=n.value;queueSave();if(['dialogue','caption','bubblePosition','captionPosition'].includes(n.dataset.panelField)){document.querySelectorAll(`[data-preview="${p.id}"]`).forEach(previewNode=>{previewNode.innerHTML=preview(p,{edit:!!previewNode.closest('#reader')});hydrate(previewNode);});}}});
document.addEventListener('change',async ev=>{const n=ev.target;try{
  if(n.dataset.bind==='episode-cast'){const e=episode();e.cast=n.checked?[...new Set([...e.cast,n.value])]:e.cast.filter(x=>x!==n.value);await save();}
  if(n.dataset.panelCast){const p=panelById(n.dataset.panelCast);p.cast=n.checked?[...new Set([...p.cast,n.value])]:p.cast.filter(x=>x!==n.value);await save();}
  if(n.dataset.pageLayout){episode().pages.find(p=>p.id===n.dataset.pageLayout).layout=n.value;await save();}
  if(n.id==='referenceFile'&&n.files[0])await run(async()=>{draft=collectCharacter();draft.refId=await putAsset(await rasterize(n.files[0]));drawCharacterForm();});
  if(n.id==='importFile')await run(()=>importBackup(n.files[0]));
  if(n.id==='appearancePreset'){const sets={explorer:{body:'Athletic adult build',hair:'Wavy chestnut hair',outfit:'Copper flight jacket, dark trousers, sturdy boots',tattoos:'Fine-line constellation on the forearm'},noir:{body:'Tall adult build',hair:'Sleek dark hair',outfit:'Charcoal trench coat over a fully buttoned shirt',tattoos:'Geometric sleeve on the left arm'},artist:{body:'Soft, strong adult build',hair:'Loose silver curls',outfit:'Rolled-sleeve linen shirt and high-waisted trousers',tattoos:'Watercolor-style flowers on the shoulder'}};const v=sets[n.value];if(v){for(const [k,value] of Object.entries(v))$('#characterForm').elements[k].value=value;}}
}catch(e){notify(e.message,true);}});
$('#lettering').addEventListener('cancel',ev=>{ev.preventDefault();closeLettering().catch(err=>notify(err.message,true));});
let swipe=null;$('#reader').addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;swipe={x:e.clientX,y:e.clientY};});$('#reader').addEventListener('pointerup',e=>{if(!swipe)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;swipe=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5)moveReader(dx<0?1:-1);});$('#reader').addEventListener('pointercancel',()=>swipe=null);document.addEventListener('keydown',e=>{if($('#reader').open){if(e.key==='ArrowRight')moveReader(1);if(e.key==='ArrowLeft')moveReader(-1);}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save().catch(()=>{});});
try{lib=await getLibrary()||blankLibrary();render();}catch(e){$('#app').innerHTML=`<section class="card"><h1>Storage isn’t available.</h1><p>${esc(e.message)}</p><p>Use a normal browser window with website storage enabled. Nothing was sent to a provider.</p></section>`;}
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>notify('Offline installation is unavailable here. Use HTTPS or localhost.'));
